from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != bg and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            comps.append(comp)
    if not comps:
        return [row[:] for row in grid]
    # The multi-cell object is the stamp; isolated pixels are its targets.
    motif = max(comps, key=len)
    if len(motif) < 2:
        return [row[:] for row in grid]
    r0 = min(r for r,c in motif); r1 = max(r for r,c in motif)
    c0 = min(c for r,c in motif); c1 = max(c for r,c in motif)
    ar, ac = (r0+r1)//2, (c0+c1)//2
    pattern = [(r-ar, c-ac, grid[r][c]) for r,c in motif]
    out = [row[:] for row in grid]
    for comp in comps:
        if comp is motif or len(comp) != 1:
            continue
        tr, tc = comp[0]
        for dr, dc, color in pattern:
            y, x = tr+dr, tc+dc
            if 0 <= y < h and 0 <= x < w:
                out[y][x] = color
    return out

