def transform(grid):
    """Copy the largest non-background object centered on every isolated marker."""
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r,c) in seen:
                continue
            q = deque([(r,c)])
            seen.add((r,c))
            comp=[]
            while q:
                y,x=q.popleft(); comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    z=(y+dy,x+dx)
                    if 0<=z[0]<h and 0<=z[1]<w and z not in seen and grid[z[0]][z[1]]!=bg:
                        seen.add(z); q.append(z)
            comps.append(comp)
    source=max(comps,key=len)
    sr0=min(r for r,c in source); sr1=max(r for r,c in source)
    sc0=min(c for r,c in source); sc1=max(c for r,c in source)
    # All non-background cells outside the main object are placement markers.
    markers=[(r,c) for comp in comps if comp is not source for r,c in comp]
    out=[row[:] for row in grid]
    # Keep the source unchanged; stamp its bounding-box pattern centered at each marker.
    cr=(sr0+sr1)//2; cc=(sc0+sc1)//2
    for mr,mc in markers:
        for r in range(sr0,sr1+1):
            for c in range(sc0,sc1+1):
                v=grid[r][c]
                if v != bg:
                    y=mr+(r-cr); x=mc+(c-cc)
                    if 0<=y<h and 0<=x<w:
                        out[y][x]=v
    return out

from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] != 0:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            bounds = {}
            for y, x in cells:
                color = grid[y][x]
                if color not in bounds:
                    bounds[color] = [y, y, x, x]
                else:
                    b = bounds[color]
                    b[0] = min(b[0], y); b[1] = max(b[1], y)
                    b[2] = min(b[2], x); b[3] = max(b[3], x)
            colors = sorted(bounds, key=lambda color: -((bounds[color][1]-bounds[color][0]+1)*(bounds[color][3]-bounds[color][2]+1)))
            mapping = dict(zip(colors, reversed(colors)))
            for y, x in cells:
                out[y][x] = mapping[grid[y][x]]
    return out

def transform(grid):
    """Copy the rare non-background shape onto matching all-zero placements."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            if value != 0:
                counts[value] = counts.get(value, 0) + 1
    shape_color = min(counts, key=counts.get)
    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] == shape_color]
    r_min = min(r for r, _ in points)
    c_min = min(c for _, c in points)
    shape = [(r - r_min, c - c_min) for r, c in points]

    result = [row[:] for row in grid]
    for r0 in range(h):
        for c0 in range(w):
            cells = [(r0 + dr, c0 + dc) for dr, dc in shape]
            if (all(0 <= r < h and 0 <= c < w for r, c in cells)
                    and all(grid[r][c] == 0 for r, c in cells)):
                for r, c in cells:
                    result[r][c] = shape_color
    return result

from collections import Counter

def _runs(indices):
    if not indices:
        return []
    out=[]; start=prev=indices[0]
    for x in indices[1:]:
        if x != prev+1:
            out.append((start,prev)); start=x
        prev=x
    out.append((start,prev))
    return out

def transform(grid):
    a=[row[:] for row in grid]
    h,w=len(a),len(a[0])
    counts=Counter(v for row in a for v in row)
    bg=counts.most_common(1)[0][0]
    colors=[c for c in counts if c!=bg]
    # A boundary color forms paired runs on opposite sides of the grid.
    candidates=[]
    for c in colors:
        left=_runs([r for r in range(h) if a[r][0]==c])
        right=_runs([r for r in range(h) if a[r][w-1]==c])
        top=_runs([x for x in range(w) if a[0][x]==c])
        bottom=_runs([x for x in range(w) if a[h-1][x]==c])
        if left and right and max(y-x+1 for x,y in left)>=2 and max(y-x+1 for x,y in right)>=2:
            candidates.append((c,'v',left,right))
        if top and bottom and max(y-x+1 for x,y in top)>=2 and max(y-x+1 for x,y in bottom)>=2:
            candidates.append((c,'h',top,bottom))
    if not candidates:
        return a
    marker,orient,first,second=max(candidates,key=lambda z: sum(counts[z[0]] for _ in [0]))
    signals=[c for c in colors if c!=marker]
    if not signals:
        return a
    sig=max(signals,key=lambda c: counts[c])
    if orient=='v':
        left,right=first,second
        # Pick the marker stripe that contains the signal pattern as its source.
        def contained_count(bands):
            return max((sum(1 for r in range(lo,hi+1) for x in range(w) if a[r][x]==sig) for lo,hi in bands),default=0)
        nl,nr=contained_count(left),contained_count(right)
        if max(nl,nr)==0:
            return a
        if nl>=nr:
            source, dest, source_side, dest_side=left,right,'left','right'
        else:
            source, dest, source_side, dest_side=right,left,'right','left'
        slo,shi=max(source,key=lambda b:sum(1 for r in range(b[0],b[1]+1) for x in range(w) if a[r][x]==sig))
        dlo,dhi=min(dest,key=lambda b:abs((b[1]-b[0])-(shi-slo)))
        # Each signal cell extends toward its boundary marker; the endpoint is marked 4.
        for r in range(slo,shi+1):
            for x in range(w):
                if a[r][x]!=sig: continue
                a[r][x]=4
                if source_side=='left':
                    for xx in range(1,x):
                        if a[r][xx]==bg: a[r][xx]=sig
                else:
                    for xx in range(x+1,w-1):
                        if a[r][xx]==bg: a[r][xx]=sig
        # Copy the active row pattern to the opposite stripe and fill inward.
        active=[r for r in range(slo,shi+1) if any(grid[r][x]==sig for x in range(w))]
        for r in active:
            rr=dlo+(r-slo)
            if rr<dlo or rr>dhi: continue
            if dest_side=='left':
                for x in range(1,w):
                    if a[rr][x]==bg: a[rr][x]=sig
            else:
                for x in range(0,w-1):
