def transform(grid):
    """Count upright and inverted T tetrominoes and encode each count in a panel."""
    h, w = len(grid), len(grid[0]) if grid else 0
    seen = set()
    upward = downward = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            if len(cells) != 4:
                continue
            rows = {}
            for y, x in cells:
                rows.setdefault(y, []).append(x)
            bars = [(y, sorted(xs)) for y, xs in rows.items() if len(xs) == 3]
            if len(bars) != 1:
                continue
            bar_y, bar_xs = bars[0]
            if bar_xs != list(range(bar_xs[0], bar_xs[0] + 3)):
                continue
            center = bar_xs[1]
            stem = [p for p in cells if p[0] != bar_y]
            if len(stem) != 1 or stem[0][1] != center or abs(stem[0][0] - bar_y) != 1:
                continue
            if stem[0][0] < bar_y:
                upward += 1
            else:
                downward += 1

    out = [[0] * 6 for _ in range(3)]
    slots = ((0, 0), (0, 2), (2, 0), (2, 2))
    for value, count, offset in ((3, upward, 0), (1, downward, 3)):
        for rr, cc in slots[:min(count, len(slots))]:
            out[rr][cc + offset] = value
    return out

